{"revision": "e41515de6f7efb19b43293ab49cb967cd64ab9f9", "scope": "DuckDB public C API v1 selected source contracts; no build/DB/source program execution or full runtime proof.", "evidence": [{"id": "D1", "path": "src/include/duckdb.h", "lines": [6509, 6525], "source_sha256": "0a938c1a9e2a98b8039226266ead3ee0c89c7fcb9962de49e8b551d5eeae91df", "quote": "/*!
 * Executes a SQL query within a connection and stores the full (materialized) result in the out_result pointer. If the
 * query fails to execute, DuckDBError is returned and the error message can be retrieved by calling
 * `duckdb_result_error`.
 *
 * Note that after running `duckdb_query`, `duckdb_destroy_result` must be called on the result object even if the query
 * fails, otherwise the error stored within the result will not be freed correctly.
 *
 * history:
 * - stable: v0.1.0
 *
 * @param connection The connection to perform the query in.
 * @param query The SQL query to run.
 * @param out_result The query result.
 * @return duckdb_state
 */
DUCKDB_C_API duckdb_state duckdb_query(duckdb_connection connection, const char *query, duckdb_result *out_result);"}, {"id": "D2", "path": "src/include/duckdb.h", "lines": [6651, 6663], "source_sha256": "0a938c1a9e2a98b8039226266ead3ee0c89c7fcb9962de49e8b551d5eeae91df", "quote": "#if DUCKDB_API_VERSION_AT_LEAST(0, 2, 9)
/*!
 * Returns the error message contained within the result. The error is only set if `duckdb_query` returns `DuckDBError`.
 *
 * The result of this function must not be freed. It will be cleaned up when `duckdb_destroy_result` is called.
 *
 * history:
 * - stable: v0.2.9
 *
 * @param result The result object to fetch the error from.
 * @return const char*
 */
DUCKDB_C_API const char *duckdb_result_error(duckdb_result *result);"}, {"id": "D3", "path": "src/main/capi/v1/result-c.cpp", "lines": [611, 627], "source_sha256": "4a0d7249d229c1aeb6fd1287718ce088c91536b978e7cbb493cb1e915103c550", "quote": "const char *duckdb_result_error(duckdb_result *result) {
	if (!result || !result->internal_data) {
		return nullptr;
	}
	auto &result_data = *(reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data));
	return !result_data.HasError() ? nullptr : result_data.GetError().c_str();
}

duckdb_error_type duckdb_result_error_type(duckdb_result *result) {
	if (!result || !result->internal_data) {
		return DUCKDB_ERROR_INVALID;
	}
	auto &result_data = *(reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data));
	if (!result_data.HasError()) {
		return DUCKDB_ERROR_INVALID;
	}
	return duckdb::ErrorTypeToC(result_data.GetErrorType());"}, {"id": "D4", "path": "src/main/capi/v1/duckdb-c.cpp", "lines": [194, 202], "source_sha256": "da75f396f2223b5dfd629e6aae7a6aa99b0ef59e77cebe56cd37b45cd67fc299", "quote": "duckdb_state duckdb_query(duckdb_connection connection, const char *query, duckdb_result *out) {
	Connection *conn = reinterpret_cast<Connection *>(connection);
	try {
		auto result = conn->Query(query);
		return DuckDBTranslateResult(std::move(result), out);
	} catch (...) {
		return DuckDBError;
	}
}"}, {"id": "D5", "path": "src/main/capi/v1/result-c.cpp", "lines": [350, 376], "source_sha256": "4a0d7249d229c1aeb6fd1287718ce088c91536b978e7cbb493cb1e915103c550", "quote": "duckdb_state DuckDBTranslateResult(unique_ptr<QueryResult> result_p, duckdb_result *out) {
	auto &result = *result_p;
	D_ASSERT(result_p);
	if (!out) {
		// no result to write to, only return the status
		return !result.HasError() ? DuckDBSuccess : DuckDBError;
	}

	memset(out, 0, sizeof(duckdb_result));

	// initialize the result_data object
	auto result_data = new DuckDBResultData();
	result_data->result = std::move(result_p);
	result_data->result_set_type = CAPIResultSetType::CAPI_RESULT_TYPE_NONE;
	out->internal_data = result_data;

	if (result.HasError()) {
		// write the error message
		out->deprecated_error_message = (char *)result.GetError().c_str(); // NOLINT
		return DuckDBError;
	}
	// copy the data
	// first write the metadata
	out->deprecated_column_count = result.ColumnCount();
	out->deprecated_rows_changed = 0;
	return DuckDBSuccess;
}"}, {"id": "D6", "path": "src/main/capi/v1/result-c.cpp", "lines": [494, 506], "source_sha256": "4a0d7249d229c1aeb6fd1287718ce088c91536b978e7cbb493cb1e915103c550", "quote": "void duckdb_destroy_result(duckdb_result *result) {
	if (result->deprecated_columns) {
		for (idx_t i = 0; i < result->deprecated_column_count; i++) {
			DuckdbDestroyColumn(result->deprecated_columns[i], result->deprecated_row_count);
		}
		duckdb_free(result->deprecated_columns);
	}
	if (result->internal_data) {
		auto result_data = reinterpret_cast<duckdb::DuckDBResultData *>(result->internal_data);
		delete result_data;
	}
	memset(result, 0, sizeof(duckdb_result));
}"}], "questions": [{"qid": "Q001", "question_en": "Does the public API contract require duckdb_destroy_result for the result object even when duckdb_query fails?", "question_pt": "O contrato público exige duckdb_destroy_result para o objeto de resultado mesmo quando duckdb_query falha?"}, {"qid": "Q002", "question_en": "Should the caller manually free the pointer returned by duckdb_result_error?", "question_pt": "O chamador deve liberar manualmente o ponteiro retornado por duckdb_result_error?"}, {"qid": "Q003", "question_en": "Does the selected duckdb_result_error implementation return nullptr when result is null or result->internal_data is null?", "question_pt": "A implementação selecionada de duckdb_result_error retorna nullptr quando result é nulo ou result->internal_data é nulo?"}, {"qid": "Q004", "question_en": "Does the catch (...) branch of the selected duckdb_query guarantee that out is initialized and contains an error message?", "question_pt": "O ramo catch (...) da implementação selecionada de duckdb_query garante que out seja inicializado e contenha uma mensagem de erro?"}]}
